(function () {
	'use strict';

	var visualizationModule = angular.module('visualization', ['datasets-api']);

	visualizationModule.factory('visualizationModalService', ['$uibModal', function ($uibModal) {

		var visualizationModalService = {};

		visualizationModalService.openModal = function (datasetId, observationUnitsSearch) {
			return $uibModal.open({
				templateUrl: '/Fieldbook/static/angular-templates/visualization/visualizationModal.html',
				controller: 'visualizationModalController',
				size: 'md',
				resolve: {
					datasetId: function () {
						return datasetId;
					},
					observationUnitsSearch: function () {
						return observationUnitsSearch;
					}
				}
			});
		};

		visualizationModalService.showImageModal = function (imageUrl) {
			return $uibModal.open({
				templateUrl: '/Fieldbook/static/angular-templates/visualization/showImageModal.html',
				controller: 'showImageModalController',
				size: 'lg',
				resolve: {
					imageUrl: function () {
						return imageUrl;
					}
				}
			});
		};

		return visualizationModalService;

	}]);

	visualizationModule.controller('visualizationModalController', ['$scope', '$timeout', '$uibModalInstance', 'datasetService',
		'datasetId', 'observationUnitsSearch', 'visualizationModalService',
		function ($scope, $timeout, $uibModalInstance, datasetService, datasetId, observationUnitsSearch, visualizationModalService) {

			var OBSERVATION_UNIT_ID = 8201;
			var PLOT_TYPES = {
				SCATTERPLOT: 'Scatterplot',
				BOXPLOT: 'Boxplot',
				HISTOGRAM: 'Histogram'
			};

			$scope.rCalls = [];
			$scope.selection = {selectedRCall: null, selectedVariableX: null, selectedVariableY: null, selectedTraits: [], selectedColor: null};
			$scope.variates = [];
			$scope.factors = [];
			this.$onInit = function () {
				$scope.init();
			}

			$scope.$watch('selection.selectedRCall', function () {
				$timeout(function () {
					$scope.selection.selectedVariableX = null;
					$scope.selection.selectedVariableY = null;
                    $scope.selection.selectedColor = null;
				}, 0);
			});

			$scope.init = function () {
                $scope.rCalls = [
                    {description: 'Scatterplot', parameters: {x: null, y: null}},
                    {description: 'Boxplot', parameters: {x: null, y: null}},
                    {description: 'Histogram', parameters: {x: null, binwidth: null}},
                    {description: 'Correlation matrix', parameters: {}},
                    {description: 'Ranked germplasm', parameters: {x: null}}
                ];
                $scope.selection.selectedRCall = $scope.rCalls[0];
				datasetService.getColumns(datasetId, observationUnitsSearch.draftMode).then(function (columnsData) {

					var variateVariableTypes = ['TRAIT', 'SELECTION_METHOD'];

					$scope.variates = columnsData.filter(column => {
						return variateVariableTypes.includes(column.variableType) && (column.dataTypeId == null || column.dataTypeId === 1110);
					});
					$scope.selection.selectedTraits = $scope.variates.slice(0, 6);
                    var gid = columnsData.find(c => c.termId === 8240 || c.name === 'GID');
                    var designation = columnsData.find(c => c.termId === 8250 || c.name === 'DESIGNATION');
                    $scope.identityKey = gid && gid.name;
                    $scope.identityLabelKey = designation && designation.name;
                    $scope.factors = columnsData.filter(column => {
						return !variateVariableTypes.includes(column.variableType) && OBSERVATION_UNIT_ID !== column.termId;
					});
				}).catch(function () { showErrorMessage('', 'Unable to load variables. Please close and try again.'); });
			};

			$scope.cancel = function () {
				$uibModalInstance.close();
			};

            var destroyed = false;
            $scope.$on('$destroy', function () { destroyed = true; });
            $scope.generate = function () {
                var selection = angular.copy($scope.selection);
                if ($scope.isExporting || !validate(selection.selectedRCall, selection.selectedVariableX, selection.selectedVariableY)) return;
                $scope.isExporting = true;
                var request = angular.copy(observationUnitsSearch);
                request.filterColumns = getVisibleColumns(selection.selectedRCall, selection.selectedVariableX, selection.selectedVariableY);
                var options = {type: selection.selectedRCall.description, x: selection.selectedVariableX && selection.selectedVariableX.name,
                    y: selection.selectedVariableY && selection.selectedVariableY.name,
                    xLabel: selection.selectedVariableX && (selection.selectedVariableX.alias || selection.selectedVariableX.name),
                    yLabel: selection.selectedVariableY && (selection.selectedVariableY.alias || selection.selectedVariableY.name),
                    binWidth: selection.selectedRCall.parameters.binwidth,
                    traits: selection.selectedTraits.map(t => ({key: t.name, label: t.alias || t.name})),
                    identityKey: $scope.identityKey, identityLabelKey: $scope.identityLabelKey,
                    colorBy: selection.selectedColor && selection.selectedColor.name,
                    colorLabel: selection.selectedColor && (selection.selectedColor.alias || selection.selectedColor.name)};
                datasetService.getObservationForVisualization(datasetId, JSON.stringify(request)).then(function (data) {
                    if (destroyed) return;
                    BmsNativePlot.model(data, options);
                    visualizationModalService.showImageModal({rows: data, options: options});
                }).catch(function (error) {
                    if (!destroyed) showErrorMessage('', error.message || 'Unable to load plot data. Please try again.');
                }).finally(function () { $scope.isExporting = false; });
            };

			function validate(rCall, variableX, variableY) {
				if (!hasRequiredFields(rCall, variableX, variableY)) {
					showErrorMessage('', $.fieldbookMessages.errorPlotGraphRequiredFields);
					return false;
				}
				return true;
			}

			function hasRequiredFields(rCall, variableX, variableY) {
				if (rCall.description === 'Correlation matrix') return $scope.selection.selectedTraits.length >= 2 && $scope.selection.selectedTraits.length <= 12;
                if (rCall.description === 'Ranked germplasm') return variableX && $scope.identityKey;
                if (PLOT_TYPES.SCATTERPLOT === rCall.description) {
					return variableX && variableY;
				} else if (PLOT_TYPES.HISTOGRAM === rCall.description) {
					return variableX;
				} else if (PLOT_TYPES.BOXPLOT === rCall.description) {
					return variableX && variableY;
				}
			}

			function getVisibleColumns(rCall, selectedVariableX, selectedVariableY) {
                var keys = rCall.description === 'Correlation matrix' ? $scope.selection.selectedTraits.map(t => t.name) : [selectedVariableX && selectedVariableX.name];
                if (['Scatterplot', 'Boxplot'].includes(rCall.description)) keys.push(selectedVariableY && selectedVariableY.name);
                if ($scope.selection.selectedColor) keys.push($scope.selection.selectedColor.name);
                if ($scope.identityKey) keys.push($scope.identityKey);
                if ($scope.identityLabelKey) keys.push($scope.identityLabelKey);
                return Array.from(new Set(keys.filter(Boolean)));
			}

		}]);


	visualizationModule.controller('showImageModalController', ['$scope', '$uibModalInstance', 'imageUrl', function ($scope, $uibModalInstance, imageUrl) {

		$scope.plotData = imageUrl;

		$scope.cancel = function () {
			$uibModalInstance.close();
		};

	}]);


    visualizationModule.directive('nativePlot', function () {
        return { restrict: 'A', scope: {plotData: '=nativePlot'}, link: function (scope, element) {
            var dispose;
            scope.$watch('plotData', function (data) {
                if (dispose) dispose();
                if (data) dispose = BmsNativePlot.mount(element[0], data.rows, data.options);
            });
            scope.$on('$destroy', function () { if (dispose) dispose(); });
        }};
    });

	visualizationModule.directive('numbersOnly', function () {
		return {
			require: 'ngModel',
			link: function (scope, element, attr, ngModelCtrl) {
				function fromUser(text) {
					if (text) {
						var transformedInput = text.replace(/[^0-9.]/g, '');

						if (transformedInput !== text) {
							ngModelCtrl.$setViewValue(transformedInput);
							ngModelCtrl.$render();
						}
						return transformedInput;
					}
					return undefined;
				}

				ngModelCtrl.$parsers.push(fromUser);
			}
		};
	});

})();